// Datos inventados: una lista de entregas del día, como llegaría de un archivo CSV (zona,kg)
const csv = `Palermo,12
Caballito,5
Palermo,7
Flores,21
Almagro,4
Caballito,10`;

// Capas 1 y 2: variables, tipos y una función que valida en el borde
function leerEntregas(texto) {
  return texto.trim().split("\n").map((linea, i) => {
    const [zona, kgTexto] = linea.split(",");
    const kg = Number(kgTexto);                       // el texto se convierte acá, una vez
    if (!zona || !Number.isFinite(kg) || kg <= 0) {
      throw new Error(`línea ${i + 1}: «${linea}» no tiene zona o kg válido`);
    }
    return { zona: zona.trim(), kg };
  });
}

// Capa 3: una estructura (Map) y un algoritmo de una pasada: n pasos
function totalesPorZona(entregas) {
  const totales = new Map();
  for (const { zona, kg } of entregas) {
    totales.set(zona, (totales.get(zona) ?? 0) + kg);
  }
  return totales;
}

// Capa 4: el máximo con su invariante y una regla de desempate escrita
function zonaMasPesada(totales) {
  let mejor = null;                                    // invariante: «mejor» es la ganadora de lo ya visto
  for (const [zona, kg] of totales) {
    if (mejor === null || kg > mejor.kg || (kg === mejor.kg && zona < mejor.zona)) {
      mejor = { zona, kg };
    }
  }
  return mejor;
}

const resultado = zonaMasPesada(totalesPorZona(leerEntregas(csv)));
console.log("Zona más pesada:", resultado);

